package dev.youth;import java.time.*;import java.util.*;
public final class AvailabilityNormalizer {public List<Scheduler.Slot> merge(List<Scheduler.Slot> slots){var grouped=new TreeMap<String,List<Scheduler.Slot>>();slots.forEach(s->grouped.computeIfAbsent(s.volunteer(),k->new ArrayList<>()).add(s));var out=new ArrayList<Scheduler.Slot>();for(var entry:grouped.entrySet()){var values=entry.getValue().stream().sorted(Comparator.comparing(Scheduler.Slot::start)).toList();for(var s:values){if(out.isEmpty()||!out.getLast().volunteer().equals(s.volunteer())||out.getLast().end().isBefore(s.start())||!out.getLast().skills().equals(s.skills()))out.add(s);else{var old=out.removeLast();out.add(new Scheduler.Slot(old.volunteer(),old.start(),old.end().isAfter(s.end())?old.end():s.end(),old.skills()));}}}return List.copyOf(out);}}
